func ballotResultAriaLabel(closed bool) string {
	if closed {
		return "Abstimmungsergebnis"
	}
	return "Zwischenstand"
}
func ballotAttachmentKind(pdf bool) string {
	if pdf {
		return "PDF"
	}
	return "Datei"
}

func ballotFilterStatus(ballot view.BallotView) string {
	if ballot.IsDraft {
		return "draft"
	}
	if ballot.IsClosed {
		return "closed"
	}
	return "open"
}

func ballotStatusCount(ballots []view.BallotView, status string) int {
	count := 0
	for _, ballot := range ballots {
		if ballotFilterStatus(ballot) == status {
			count++
		}
	}
	return count
}

